message.content:
{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "You had a knee replacement surgery on your right knee.",
          "sources": ["p1:L4", "term:TKA"]
        }
      ]
    },
    {
      "title": "Your medicines",
      "bullets": [
        {
          "id": "b2",
          "text": "Oxycodone 5 mg swallow it every 4 hours only when you need it for moderate to severe pain. Do not drive while taking.",
          "sources": ["p1:L6", "term:PO", "term:q4h", "term:PRN"]
        },
        {
          "id": "b3",
          "text": "Tylenol 1,000 mg swallow it every 8 hours scheduled for 2 weeks.",
          "sources": ["p1:L7", "term:PO", "term:q8h"]
        },
        {
          "id": "b4",
          "text": "Enoxaparin 40 mg a shot just under the skin once daily for 14 days to prevent blood clots.",
          "sources": ["p1:L8", "term:subQ"]
        },
        {
          "id": "b5",
          "text": "Docusate 100 mg swallow it two times a day while taking oxycodone.",
          "sources": ["p1:L9", "term:PO", "term:BID"]
        },
        {
          "id": "b6",
          "text": "Ondansetron 4 mg swallow it every 8 hours only when you need it for nausea.",
          "sources": ["p1:L10", "term:PO", "term:q8h", "term:PRN"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b7",
          "text": "You can put weight on your leg if it feels okay with a walker. Do exercises to help you move better 3 times per week. Ice 20 minutes every 2 hours. Keep leg elevated.",
          "sources": ["p1:L11", "term:WBAT", "term:PT"]
        },
        {
          "id": "b8",
          "text": "Keep dressing dry. No tub baths or swimming until staples are removed.",
          "sources": ["p1:L12"]
        },
        {
          "id": "b9",
          "text": "Do not drive while taking oxycodone.",
          "sources": ["p1:L6"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b10",
          "text": "See orthopedics in 2 weeks for staple removal.",
          "sources": ["p1:L13"]
        }
      ]
    }
  ],
  "med_schedule": [
    {
      "drug": "Oxycodone",
      "dose": "5 mg",
      "morning": true,
      "midday": true,
      "evening": true,
      "night": true,
      "as_needed": true,
      "note": "every 4 hours as needed",
      "sources": ["p1:L6"]
    },
    {
      "drug": "Tylenol",
      "dose": "1,000 mg",
      "morning": true,
      "midday": true,
      "evening": true,
      "night": false,
      "as_needed": false,
      "note": "every 8 hours scheduled for 2 weeks",
      "sources": ["p1:L7"]
    },
    {
      "drug": "Enoxaparin",
      "dose": "40 mg",
      "morning": true,
      "midday": false,
      "evening": false,
      "night": false,
      "as_needed": false,
      "note": "once daily for 14 days",
      "sources": ["p1:L8"]
    },
    {
      "drug": "Docusate",
      "dose": "100 mg",
      "morning": true,
      "midday": false,
      "evening": true,
      "night": false,
      "as_needed": false,
      "note": "two times a day while taking oxycodone",
      "sources": ["p1:L9"]
    },
    {
      "drug": "Ondansetron",
      "dose": "4 mg",
      "morning": true,
      "midday": true,
      "evening": true,
      "night": false,
      "as_needed": true,
      "note": "every 8 hours as needed for nausea",
      "sources": ["p1:L10"]
    }
  ],
  "call_911_if": [
    {
      "id": "w1",
      "text": "Chest pain or sudden shortness of breath - call 911 or go to the emergency room.",
      "sources": ["p1:L14", "term:ED"]
    },
    {
      "id": "w2",
      "text": "Calf pain or swelling in either leg - call the surgeon.",
      "sources": ["p1:L15", "p1:L16"]
    },
    {
      "id": "w3",
      "text": "Fever over 101.5 F - call the surgeon.",
      "sources": ["p1:L15", "p1:L17"]
    },
    {
      "id": "w4",
      "text": "Redness, warmth or drainage from the incision - call the surgeon.",
      "sources": ["p1:L15", "p1:L18"]
    }
  ],
  "questions_for_your_doctor": [
    "Should I keep taking oxycodone 5 mg?",
    "Should I keep taking Tylenol 1,000 mg?",
    "Should I keep taking enoxaparin 40 mg?",
    "Should I keep taking docusate 100 mg?",
    "Should I keep taking ondansetron 4 mg?"
  ]
}
